{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/order-table.json
    The order history as a table or as cards: number, date, items, total and a status pill, with an optional pager. Axes: layout (table, cards), pager (show, hide), tone, density.
    Props (p): id, title, orders, statuses, labels, layout, pager, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_orders = ($p['orders'] ?? null)}
{var $v_statuses = ($p['statuses'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'table')}
{var $v_pager = ($p['pager'] ?? 'show')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_11}
  {capture $c_10}
    {if ui_t(ui_eq($v_layout, 'table'))}
      {=ui_include('blocks/order-rows.latte', ['p' => ['orders' => $v_orders, 'statuses' => $v_statuses, 'labels' => $v_labels, 'density' => $v_density]])|noescape}
    {else}
      {capture $c_9}
        {foreach ui_l($v_orders) as $v_o}
          {capture $c_8}
            {capture $c_7}
              {capture $c_3}
                {capture $c_1}
                  {=ui_text(ui_get($v_o, ['number']))}
                {/capture}
                {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
                {capture $c_2}
                  {=ui_text(ui_get($v_o, ['date']))}
                {/capture}
                {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
              {/capture}
              {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0'], 'children' => $c_3])|noescape}
              {capture $c_4}
                {=ui_text(ui_tpl(ui_get($v_labels, ['itemsCount']), [ui_get($v_o, ['items'])]))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm'], 'children' => $c_4])|noescape}
              {capture $c_5}
                {=ui_text(ui_money(ui_get($v_o, ['total']), ui_get($v_o, ['currency'])))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'bold'], 'children' => $c_5])|noescape}
              {capture $c_6}
                {=ui_text(ui_at($v_statuses, ui_get($v_o, ['status'])))}
              {/capture}
              {=ui_include('blocks/pill.latte', ['p' => ['tone' => (ui_t(ui_eq(ui_get($v_o, ['status']), 'paid')) ? 'green' : (ui_t(ui_eq(ui_get($v_o, ['status']), 'shipped')) ? 'blue' : (ui_t(ui_eq(ui_get($v_o, ['status']), 'pending')) ? 'amber' : 'gray')))], 'children' => $c_6])|noescape}
            {/capture}
            {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => 'flex flex-wrap items-center justify-between gap-4'], 'children' => $c_7])|noescape}
          {/capture}
          {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'default', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_8])|noescape}
        {/foreach}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'order-cards'])], 'children' => $c_9])|noescape}
    {/if}
    {if ui_t(ui_eq($v_pager, 'show'))}
      {=ui_include('blocks/pager.latte', ['p' => ['page' => 1, 'pages' => 3, 'summary' => ui_tpl(ui_get($v_labels, ['summary']), [1, 4, 12]), 'previousLabel' => ui_get($v_labels, ['previous']), 'nextLabel' => ui_get($v_labels, ['next'])]])|noescape}
    {/if}
  {/capture}
  {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch'], 'children' => $c_10])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_11])|noescape}
